$ErrorActionPreference = 'Stop'
$phaseWatch = [System.Diagnostics.Stopwatch]::StartNew()
$maximumMs = 15000
$evidenceReserveMs = 500
$maximumPayloadBytes = 8192
$fixture = 'E:\projects\ladybug\repro\feat010-menu-clock-repair-20261018\controller-integration-20261019\evidence\fsa-module-path-diagnosis\fsa-command-environment-diagnostic.ps1'
$resultPath = 'E:\projects\ladybug\repro\feat010-menu-clock-repair-20261018\controller-integration-20261019\evidence\fsa-module-path-diagnosis\fsa-command-environment-result.json'
$outerImage = 'C:\Users\19029\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe'
$outerVersion = '7.6.5'
$expectedOuterImageSha = '362a356ce7f0940ec74f73a8fc2c990a2cc24a38a11c90bbd8eca947110ad139'
$nativeImage = 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
$expectedNativeImageSha = '60c9b29843624dd8af6b6a7b26147753be6aeef65098b9a503cc50850afe410f'
$expectedFixtureSha = '8072e577f983cbab931563b108959c4c5d7015068fb244907df5db262cb3d1d9'
$bundledCoreModuleDirectory = 'c:\users\19029\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\Modules'
$expectedOuterModulePathEntries = @(
    'C:\Users\19029\Documents\PowerShell\Modules'
    'C:\Program Files\PowerShell\Modules'
    'c:\users\19029\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\Modules'
    'C:\Users\19029\Documents\WindowsPowerShell\Modules'
    'C:\Program Files\WindowsPowerShell\Modules'
    'C:\WINDOWS\system32\WindowsPowerShell\v1.0\Modules'
)
$expectedChildModulePathEntries = @(
    'C:\Users\19029\Documents\PowerShell\Modules'
    'C:\Program Files\PowerShell\Modules'
    'C:\Users\19029\Documents\WindowsPowerShell\Modules'
    'C:\Program Files\WindowsPowerShell\Modules'
    'C:\WINDOWS\system32\WindowsPowerShell\v1.0\Modules'
)
$corePathMatches = @($expectedOuterModulePathEntries | Where-Object { $_ -ieq $bundledCoreModuleDirectory })
if ($corePathMatches.Count -ne 1) { throw 'Frozen outer path must contain exactly one bundled Core directory.' }
$derivedChildModulePathEntries = @($expectedOuterModulePathEntries | Where-Object { $_ -ine $bundledCoreModuleDirectory })
if ($derivedChildModulePathEntries.Count -ne 5 -or (($derivedChildModulePathEntries -join ';') -cne ($expectedChildModulePathEntries -join ';'))) {
    throw 'Frozen child path is not the exact ordered one-entry subtraction.'
}
$expectedOuterModulePath = $expectedOuterModulePathEntries -join ';'
$expectedChildModulePath = $expectedChildModulePathEntries -join ';'
$expectedUtility7Path = 'C:\users\19029\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\Modules\Microsoft.PowerShell.Utility\Microsoft.PowerShell.Utility.psd1'
$expectedUtility7Base = 'C:\users\19029\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\Modules\Microsoft.PowerShell.Utility'
$expectedUtility3Path = 'C:\WINDOWS\system32\WindowsPowerShell\v1.0\Modules\Microsoft.PowerShell.Utility\Microsoft.PowerShell.Utility.psd1'
$expectedUtility3Base = 'C:\WINDOWS\system32\WindowsPowerShell\v1.0\Modules\Microsoft.PowerShell.Utility'
$utf8 = New-Object System.Text.UTF8Encoding($false, $true)
$runner = $null
$started = $false
$exitConfirmed = $false
$nativeExit = $null
$nativePid = $null
$nativeStartTicks = $null
$childLimit = $null
$childBytes = 0
$outerPayloadBytes = 0
$failure = $null
$failureTruncated = $false
$childContextAdmitted = $false
$childHypothesisMatched = $null
$childHypothesisOutcome = 'NOT_EVALUATED'
function Require-FsaContext {
    param([object]$Value, [string]$Context)
    $keys = @('schema','context','source_path','source_sha256','powershell_path','powershell_version','ps_module_path','autoload_preference','hash_command','commands','negative_command_available','utility_modules','marker_write_calls_completed')
    if ($null -eq $Value -or $Value -is [System.Array]) { throw 'Context object missing' }
    $actual = @($Value.PSObject.Properties.Name)
    if ($actual.Count -ne $keys.Count) { throw 'Context key inventory mismatch' }
    foreach ($key in $keys) { if ($actual -cnotcontains $key) { throw 'Context key missing' } }
    if ($Value.schema -isnot [string] -or $Value.schema -cne 'ladybug.feat010.fsa-e.context.v1' -or $Value.context -isnot [string] -or $Value.context -cne $Context) { throw 'Context schema or role mismatch' }
    if ($Value.source_path -isnot [string] -or [IO.Path]::GetFullPath($Value.source_path) -ine [IO.Path]::GetFullPath($fixture) -or $Value.source_sha256 -isnot [string] -or $Value.source_sha256 -cne $expectedFixtureSha) { throw 'Context fixture identity mismatch' }
    $expectedImagePath = if ($Context -ceq 'Outer') { $outerImage } else { $nativeImage }
    $expectedRoleImageSha = if ($Context -ceq 'Outer') { $expectedOuterImageSha } else { $expectedNativeImageSha }
    $expectedVersion = if ($Context -ceq 'Outer') { $outerVersion } else { '5.1.26100.9711' }
    $expectedModulePath = if ($Context -ceq 'Outer') { $expectedOuterModulePath } else { $expectedChildModulePath }
    if ($Value.powershell_path -isnot [string] -or [IO.Path]::GetFullPath($Value.powershell_path) -ine [IO.Path]::GetFullPath($expectedImagePath) -or $Value.powershell_version -isnot [string] -or $Value.powershell_version -cne $expectedVersion -or $Value.ps_module_path -isnot [string] -or $Value.ps_module_path -cne $expectedModulePath) { throw 'Context role identity, version or module path mismatch' }
    if ($null -eq $Value.autoload_preference -or $Value.autoload_preference.is_set -isnot [bool] -or ($null -ne $Value.autoload_preference.value -and $Value.autoload_preference.value -isnot [string]) -or (-not $Value.autoload_preference.is_set -and $null -ne $Value.autoload_preference.value)) { throw 'Auto-loading preference type mismatch' }
    if ($Value.autoload_preference.is_set -or $null -ne $Value.autoload_preference.value) { throw 'Auto-loading preference must remain unset' }
    $hash = $Value.hash_command
    if ($null -eq $hash -or $hash.attempted -isnot [bool] -or -not $hash.attempted -or $hash.success -isnot [bool] -or $hash.error_truncated -isnot [bool] -or $hash.error_truncated) { throw 'Hash observation incomplete or truncated' }
    if ($hash.success) {
        if ($hash.sha256 -isnot [string] -or $hash.sha256 -cne $expectedRoleImageSha -or $null -ne $hash.error) { throw 'Successful hash observation mismatch' }
    } elseif ($null -ne $hash.sha256 -or $hash.error -isnot [string] -or $hash.error.Length -eq 0) { throw 'Failed hash observation incomplete' }
    if ($Value.commands -isnot [System.Array] -or $Value.utility_modules -isnot [System.Array]) { throw 'Command or module inventory is not an array' }
    if ($hash.success -and $Value.commands.Count -eq 0) { throw 'Successful hash lacks imported command provenance' }

    foreach ($command in $Value.commands) {
        $names = @($command.PSObject.Properties.Name)
        foreach ($key in @('name','command_type','source','module_name','module_version','module_path','script_file')) {
            if ($names -cnotcontains $key -or ($null -ne $command.PSObject.Properties[$key].Value -and $command.PSObject.Properties[$key].Value -isnot [string])) { throw 'Command provenance incomplete' }
        }
        if ($names.Count -ne 7 -or $command.name -cne 'Get-FileHash' -or [string]::IsNullOrEmpty($command.command_type)) { throw 'Command provenance identity mismatch' }
    }
    foreach ($module in $Value.utility_modules) {
        $names = @($module.PSObject.Properties.Name)
        foreach ($key in @('name','version','path','module_base')) {
            if ($names -cnotcontains $key -or $module.PSObject.Properties[$key].Value -isnot [string]) { throw 'Utility module metadata incomplete' }
        }
        if ($names.Count -ne 4 -or $module.name -cne 'Microsoft.PowerShell.Utility') { throw 'Utility module identity mismatch' }
    }
    if ($Context -ceq 'Outer') {
        if (-not $hash.success) { throw 'Outer hash baseline drift' }
        if ($Value.commands.Count -ne 1) { throw 'Outer Get-FileHash command baseline mismatch' }
        $outerCommand = $Value.commands[0]
        if ($outerCommand.name -cne 'Get-FileHash' -or $outerCommand.command_type -cne 'Cmdlet' -or $outerCommand.source -cne 'Microsoft.PowerShell.Utility' -or $outerCommand.module_name -cne 'Microsoft.PowerShell.Utility' -or $outerCommand.module_version -cne '7.0.0.0' -or $outerCommand.module_path -ine $expectedUtility7Path -or $null -ne $outerCommand.script_file) {
            throw 'Outer Utility7 Cmdlet provenance baseline mismatch'
        }
        if ($Value.utility_modules.Count -ne 1) { throw 'Outer Utility inventory baseline mismatch' }
        $outerUtility = $Value.utility_modules[0]
        if ($outerUtility.name -cne 'Microsoft.PowerShell.Utility' -or $outerUtility.version -cne '7.0.0.0' -or $outerUtility.path -ine $expectedUtility7Path -or $outerUtility.module_base -ine $expectedUtility7Base) {
            throw 'Outer Utility7 inventory baseline mismatch'
        }
    } else {
        $nativeUtilityModules = @($Value.utility_modules | Where-Object {
            $_.name -ceq 'Microsoft.PowerShell.Utility' -and
            $_.version -ceq '3.1.0.0' -and
            $_.path -ieq $expectedUtility3Path -and
            $_.module_base -ieq $expectedUtility3Base
        })
        if ($nativeUtilityModules.Count -lt 1) { throw 'Native Utility3.1 inventory is missing' }
    }
    if ($Value.negative_command_available -isnot [bool] -or $Value.negative_command_available) { throw 'Missing-command negative control failed' }
    if ($Value.marker_write_calls_completed -isnot [bool] -or $Value.marker_write_calls_completed -ne ($Context -ceq 'Child')) { throw 'Marker write-call evidence mismatch' }
}
try {
    if ([IO.File]::Exists($resultPath)) { throw 'One-shot diagnostic receipt already exists' }
    if ((Get-FileHash -LiteralPath $nativeImage -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedNativeImageSha) { throw 'Pinned native PowerShell image mismatch' }
    if ((Get-FileHash -LiteralPath $fixture -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedFixtureSha) { throw 'Frozen diagnostic source mismatch' }
    $outer = & $fixture -Context Outer -MaximumBytes $maximumPayloadBytes
    $outerJson = ConvertTo-Json -InputObject $outer -Depth 8 -Compress
    $outerLine = 'FSA_E_OUTER ' + $outerJson
    $outerPayloadBytes = $utf8.GetByteCount($outerLine + [Environment]::NewLine)
    $childLimit = $maximumPayloadBytes - $outerPayloadBytes - 1024
    if ($childLimit -lt 512) { throw 'Insufficient remaining diagnostic payload budget' }
    [Console]::Error.WriteLine($outerLine)
    Require-FsaContext $outer 'Outer'
    if (-not $outer.hash_command.success) { throw 'Outer hash baseline drift' }
    if ($phaseWatch.ElapsedMilliseconds -ge ($maximumMs - $evidenceReserveMs)) { throw 'Outer query consumed whole diagnostic budget' }
    $runner = New-Object System.Diagnostics.Process
    $runner.StartInfo = New-Object System.Diagnostics.ProcessStartInfo
    $runner.StartInfo.FileName = $nativeImage
    $runner.StartInfo.Arguments = '-NoProfile -File "' + $fixture + '" -Context Child -MaximumBytes ' + $childLimit.ToString([Globalization.CultureInfo]::InvariantCulture)
    $runner.StartInfo.UseShellExecute = $false
    $runner.StartInfo.CreateNoWindow = $true
    $runner.StartInfo.RedirectStandardOutput = $false
    $runner.StartInfo.RedirectStandardError = $false
    $runner.StartInfo.EnvironmentVariables['PSModulePath'] = $expectedChildModulePath
    $started = $runner.Start()
    if (-not $started) { throw 'Diagnostic child did not start' }
    $nativePid = $runner.Id
    $nativeStartTicks = $runner.StartTime.ToUniversalTime().Ticks
    $remaining = [int]($maximumMs - $evidenceReserveMs - $phaseWatch.ElapsedMilliseconds)
    if ($remaining -le 0) { throw 'No positive diagnostic wait budget remains' }
    $exitConfirmed = $runner.WaitForExit($remaining)
    if (-not $exitConfirmed) { throw 'Diagnostic direct child exit unconfirmed' }
    $nativeExit = $runner.ExitCode
    if ($nativeExit -isnot [int] -or $nativeExit -ne 0) { throw 'Diagnostic child exit was not integer zero' }
    $stream = [IO.File]::OpenRead($resultPath)
    $retained = [IO.MemoryStream]::new([int]$childLimit)
    try {
        $chunk = New-Object byte[] 4096
        while ($true) {
            if ($phaseWatch.ElapsedMilliseconds -ge ($maximumMs - $evidenceReserveMs)) { throw 'Diagnostic receipt read deadline reached' }
            $request = [int][Math]::Min(4096, ($childLimit - $retained.Length + 1))
            $count = $stream.Read($chunk, 0, $request)
            if ($phaseWatch.ElapsedMilliseconds -ge ($maximumMs - $evidenceReserveMs)) { throw 'Diagnostic receipt read returned after deadline' }
            if ($count -eq 0) { break }
            if ($retained.Length + $count -gt $childLimit) { throw 'Diagnostic receipt exceeds remaining payload cap' }
            $retained.Write($chunk, 0, $count)
        }
        $childBytes = [int]$retained.Length
        if ($phaseWatch.ElapsedMilliseconds -ge ($maximumMs - $evidenceReserveMs)) { throw 'Diagnostic decode deadline reached' }
        $childJson = $utf8.GetString($retained.GetBuffer(), 0, $childBytes)
    } finally { $stream.Dispose(); $retained.Dispose() }
    $child = ConvertFrom-Json -InputObject $childJson -ErrorAction Stop
    Require-FsaContext $child 'Child'
    $childContextAdmitted = $true
    $childExpectedProvenance = $false
    if ($child.commands.Count -eq 1) {
        $childCommand = $child.commands[0]
        $childExpectedProvenance = [bool](
            $childCommand.name -ceq 'Get-FileHash' -and
            $childCommand.command_type -ceq 'Function' -and
            $childCommand.module_name -ceq 'Microsoft.PowerShell.Utility' -and
            $childCommand.module_version -ceq '3.1.0.0' -and
            $childCommand.module_path -ieq $expectedUtility3Path
        )
    }
    $childHypothesisMatched = [bool]($child.hash_command.success -and $child.hash_command.sha256 -ceq $expectedNativeImageSha -and $null -eq $child.hash_command.error -and $childExpectedProvenance)
    $childHypothesisOutcome = if ($childHypothesisMatched) { 'HYPOTHESIS_MATCHED' } else { 'HYPOTHESIS_MISS' }
    if ((Get-FileHash -LiteralPath $fixture -Algorithm SHA256).Hash.ToLowerInvariant() -cne $expectedFixtureSha) { throw 'Diagnostic fixture changed during observation' }
} catch {
    $failure = $_.Exception.Message
    if ($failure.Length -gt 256) { $failure = $failure.Substring(0,256); $failureTruncated = $true }
}
$runnerHandleDisposed = $null
$runnerDisposeFailure = $null
if ($null -ne $runner) {
    try {
        $runner.Dispose()
        $runnerHandleDisposed = $true
    } catch {
        $runnerHandleDisposed = $false
        $runnerDisposeFailure = $_.Exception.Message
        if ($runnerDisposeFailure.Length -gt 256) { $runnerDisposeFailure = $runnerDisposeFailure.Substring(0, 256) }
        if ($null -eq $failure) { $failure = 'Diagnostic process handle disposal failed.' }
    }
}
$observed = [ordered]@{
    phase='FSA-E-M'; status=if ($null -ne $failure) {'DIAGNOSTIC_FAILURE'} elseif ($childContextAdmitted -and $childHypothesisMatched) {'HYPOTHESIS_MATCHED_PENDING_TOOL_VISIBILITY'} elseif ($childContextAdmitted) {'HYPOTHESIS_MISS_PENDING_TOOL_VISIBILITY'} else {'DIAGNOSTIC_FAILURE'}
    native_started=$started; pid=$nativePid; start_ticks_utc=$nativeStartTicks
    direct_exit_confirmed=$exitConfirmed; native_exit_code=$nativeExit
    elapsed_ms=$phaseWatch.ElapsedMilliseconds; maximum_ms=$maximumMs
    outer_payload_bytes=$outerPayloadBytes; child_payload_maximum_bytes=$childLimit; child_payload_bytes=$childBytes
    child_context_admitted=$childContextAdmitted; child_hypothesis_matched=$childHypothesisMatched; child_hypothesis_outcome=$childHypothesisOutcome
    failure=$failure; failure_truncated=$failureTruncated
    unresolved_child=($started -and -not $exitConfirmed); kill_attempted=$false
    runner_handle_disposed=$runnerHandleDisposed; runner_dispose_failure=$runnerDisposeFailure
}
$finalLine = 'FSA_E_PARENT_RESULT ' + (ConvertTo-Json -InputObject $observed -Depth 4 -Compress)
if ($utf8.GetByteCount($finalLine + [Environment]::NewLine) + 80 -gt 1024) { [Console]::Error.WriteLine('FSA_E_PARENT_RESULT_EXCEEDS_RESERVE'); exit 1 }
[Console]::Error.WriteLine($finalLine)
if ($null -ne $failure -or $phaseWatch.ElapsedMilliseconds -ge $maximumMs) { exit 1 }
exit 0
